using Platform;
var failed=0;
void Test(string name, Action test){try{test();Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Check(bool value){if(!value)throw new Exception("Assertion failed");}
Test("部门编辑只能维护本部门",()=>{Check(Policy.CanMaintain("editor","a","a"));Check(!Policy.CanMaintain("editor","a","b"));Check(!Policy.CanMaintain("viewer","a","a"));Check(Policy.CanMaintain("admin","a","b"));});
Test("必选自动加入并去重",()=>{var r=Policy.Resolve([new("a",true,true,null),new("b",false,true,null)],["b","b"],new(2026,11,11));Check(r.SequenceEqual(new[]{"a","b"}));});
Test("失效必选阻断",()=>{try{Policy.Resolve([new("a",true,false,null)],[],new(2026,11,11));}catch(InvalidOperationException){return;}throw new Exception("没有阻断");});
Test("旧有效期不再阻断内容",()=>Check(Policy.Resolve([new("a",false,true,new(2026,1,1))],["a"],new(2026,11,11)).Length==1));

Test("并发修订冲突",()=>{try{Policy.CheckRevision(2,1);}catch(ConflictException){return;}throw new Exception("没有阻断");});
var template=Directory.GetFiles(Directory.GetCurrentDirectory(),"*.pptx").First(f=>!Path.GetFileName(f).StartsWith("~$"));var engine=new PptEngine();
Test("解析真实32页模板",()=>Check(engine.Inspect(template).Count==32));
Test("单页导出为真实PPTX",()=>{var bytes=engine.Extract(template,12);Check(bytes.Length>100);using var z=new System.IO.Compression.ZipArchive(new MemoryStream(bytes));Check(z.GetEntry("ppt/presentation.xml")!=null);});
Test("真实模板自动组装并保留图表",()=>{var b=engine.Build(template,new Template(),[new(template,28,"运营数据")],"来访交流介绍","运行管理部","2026年11月11日");var f=Path.GetTempFileName();try{File.WriteAllBytes(f,b);var slides=engine.Inspect(f);Check(slides.Count==6);Check(slides[0].Text.Contains("来访交流介绍"));Check(slides[2].Text.Contains("运营数据"));Check(!slides[2].Text.Contains("章节板块"));using var z=new System.IO.Compression.ZipArchive(new MemoryStream(b));Check(z.Entries.Any(e=>e.FullName.Contains("charts/")&&e.FullName.EndsWith(".xml")));Check(!z.Entries.Any(e=>e.FullName.Contains("notesSlides")));}finally{File.Delete(f);}});

Test("年度标题不会被日期替换",()=>{var b=engine.Build(template,new Template(),[new(template,5,"公司概况")],"2026年度公司介绍","运行管理部","2026年11月11日");var f=Path.GetTempFileName();try{File.WriteAllBytes(f,b);var text=engine.Inspect(f)[0].Text;Check(text.Contains("2026年度公司介绍"));Check(text.Contains("2026年11月11日"));}finally{File.Delete(f);}});
Test("不同物理尺寸阻断避免裁切",()=>{var f=Path.GetTempFileName();File.Copy(template,f,true);try{using(var z=System.IO.Compression.ZipFile.Open(f,System.IO.Compression.ZipArchiveMode.Update)){var entry=z.GetEntry("ppt/presentation.xml")!;System.Xml.Linq.XDocument x;using(var stream=entry.Open())x=System.Xml.Linq.XDocument.Load(stream);var s=x.Descendants(PptPackage.P+"sldSz").First();s.SetAttributeValue("cx",12192000);s.SetAttributeValue("cy",6858000);entry.Delete();using(var stream=z.CreateEntry("ppt/presentation.xml").Open())x.Save(stream);}try{engine.Build(template,new Template(),[new(f,5,"公司概况")],"测试","部门","日期");}catch(InvalidOperationException){return;}throw new Exception("必须拒绝尺寸不一致的页面");}finally{File.Delete(f);}});

Test("九个章节自动生成三页目录",()=>{var picks=Enumerable.Range(1,9).Select(i=>new Selection(template,5,"章节"+i));var f=Path.GetTempFileName();try{File.WriteAllBytes(f,engine.Build(template,new Template(),picks,"多章节介绍","公司","2026年11月11日"));var slides=engine.Inspect(f);Check(slides.Count==24);Check(slides[2].Text.Contains("章节4"));Check(slides[3].Text.Contains("章节8"));Check(slides[4].Text.Contains("章节9"));Check(!slides[4].Text.Contains("第二部分标题"));}finally{File.Delete(f);}});
Test("合成包关系闭合且不夹带未选幻灯片",()=>{var bytes=engine.Build(template,new Template(),[new(template,28,"图表")],"结构验证","公司","2026年11月11日");using var z=new System.IO.Compression.ZipArchive(new MemoryStream(bytes));var entries=z.Entries.Select(e=>e.FullName).ToHashSet();Check(entries.Count(n=>n.StartsWith("ppt/slides/slide")&&n.EndsWith(".xml"))==6);foreach(var entry in z.Entries.Where(e=>e.FullName.EndsWith(".rels"))){using var s=entry.Open();var x=System.Xml.Linq.XDocument.Load(s);var name=entry.FullName;var parent=name=="_rels/.rels"?"root":name.Replace("/_rels/","/")[..^5];foreach(var r in x.Root!.Elements()){if((string?)r.Attribute("TargetMode")=="External")continue;var target=PptPackage.Resolve(parent,(string)r.Attribute("Target")!);Check(entries.Contains(target));}}});
Test("方案章节顺序与必选遗漏补齐",()=>{
var a=new Page{Id="a",PublishedVersionId="va",Versions=[new(){Id="va",Chapter="原章节"}]};var b=new Page{Id="b",PublishedVersionId="vb",Versions=[new(){Id="vb",Chapter="必选章节"}]};
var result=OutlineService.Resolve([a,b],[new("new","新章节","说明",["a"]),new("empty","空章节","",[])]);
Check(result.Count==2);Check(result[0].Title=="新章节");Check(result[0].Summary=="说明");Check(result[1].PageIds.SequenceEqual(new[]{"b"}));Check(a.Versions[0].Chapter=="原章节");});
Test("章节不能引用未选择页面或重复页面",()=>{var p=new Page{Id="a",PublishedVersionId="va",Versions=[new(){Id="va",Chapter="章节"}]};foreach(var chapters in new[]{new[]{new OutlineChapter("x","章节","",["unknown"])},new[]{new OutlineChapter("x","章节","",["a","a"])}}){try{OutlineService.Resolve([p],chapters);}catch(ArgumentException){continue;}throw new Exception("应阻断非法大纲");}});
Test("章节标题摘要序号与目录起始页自动同步",()=>{var f=Path.GetTempFileName();try{File.WriteAllBytes(f,engine.Build(template,new Template(),[new(template,5,"技术服务","tech","服务介绍"),new(template,6,"公司概况","intro","")],"来访介绍","示例公司","2026年11月11日",new("chinese",true,true)));var slides=engine.Inspect(f);Check(slides.Count==8);Check(slides[2].Text.Contains("一 技术服务"));Check(slides[2].Text.Contains("第 4 页"));Check(slides[2].Text.Contains("第 6 页"));Check(slides[3].Text.Contains("第一章"));Check(slides[3].Text.Contains("服务介绍"));using var z=new System.IO.Compression.ZipArchive(new MemoryStream(File.ReadAllBytes(f)));using var stream=z.GetEntry("ppt/slides/slide5.xml")!.Open();var x=System.Xml.Linq.XDocument.Load(stream);Check(x.Descendants(PptPackage.P+"cNvPr").Any(e=>(string?)e.Attribute("name")=="PlatformPageNumber"));}finally{File.Delete(f);}});
Test("目录页码必须绑定到对应标题组合",()=>{using var z=new System.IO.Compression.ZipArchive(new MemoryStream(engine.Build(template,new Template(),[new(template,5,"技术服务","tech"),new(template,6,"公司概况","intro")],"测试","公司","2026",new("arabic",true,false))));using var stream=z.GetEntry("ppt/slides/slide3.xml")!.Open();var doc=System.Xml.Linq.XDocument.Load(stream);var group=doc.Descendants(PptPackage.P+"grpSp").First(g=>string.Concat(g.Descendants(PptPackage.A+"t").Select(t=>t.Value)).Contains("01 技术服务"));Check(string.Concat(group.Descendants(PptPackage.A+"t").Select(t=>t.Value)).Contains("第 4 页"));Check(doc.Descendants(PptPackage.A+"prstGeom").Count(e=>(string?)e.Attribute("prst")=="ellipse")==2);});
Test("反复保存同一草稿只在审核通过时升版",()=>{var p=new Page();var a=VersionLifecycle.Save(p,new(){Title="草稿"});var b=VersionLifecycle.Save(p,new(){Title="修改"});Check(a.Id==b.Id);Check(p.Versions.Count==1&&b.Number==0);b.Status="pending";VersionLifecycle.Approve(p,b);Check(b.Number==1);var c=VersionLifecycle.Save(p,new(){Title="第二次"});Check(c.Number==0&&p.PublishedVersionId==b.Id);c.Status="pending";VersionLifecycle.Approve(p,c);Check(c.Number==2&&p.Versions.Count==2);});
Test("待审核编辑撤回草稿且重新提交不升版",()=>{var p=new Page();var a=VersionLifecycle.Save(p,new(){Title="原稿",Status="pending"});var b=VersionLifecycle.Save(p,new(){Title="修改稿",Status="draft"});Check(a.Id==b.Id&&p.Versions.Count==1&&b.Status=="draft"&&b.Number==0);var c=VersionLifecycle.Save(p,new(){Title="重提稿",Status="pending"});Check(c.Id==a.Id&&c.Number==0&&p.Versions.Count==1);VersionLifecycle.Approve(p,c);Check(c.Number==1);});
return failed==0?0:1;
